-- 037: the 48 problems of A453-C500 enter the duel pool.
--
-- The bank grew from 452 to 500. A duel selects only from duel_problem_pool,
-- so without this the new problems are browsable and solvable but never turn
-- up in a round -- and a reference solution was written for each of them
-- precisely so the bot can play them.
--
-- Generated by tools/problem-authoring alongside the problems themselves, so
-- the rating here is the rating the bank shows and the difficulty is derived
-- from it by the same rule as difficultyOf in app/ui/rating.ts. Regenerate
-- rather than hand-edit.

on conflict (problem_key) do update set rating = excluded.rating,
  difficulty = excluded.difficulty, topic = excluded.topic;

-- 021 marked the then-current pool bot-ready in one sweep and later additions
-- default to false, which would leave these enabled but reachable only in
-- human-vs-human duels.
update public.duel_problem_pool set bot_ready = true where enabled;
